import { useState } from "react";
import { NavLink, Link, Outlet } from "react-router-dom"; // استيراد الأجزاء المهمة

const NAV_ITEMS = [
  { id: "dashboard", label: "Dashboard", icon: "📊", href: "/student/dashboard" },
  { id: "search", label: "Find offers", icon: "🔍", href: "/student/search" },
  { id: "applications", label: "My applications", icon: "📋", href: "/student/applications" },
  { id: "profile", label: "My profile", icon: "👤", href: "/student/profile" },
];

function Sidebar({ closeMobile }) {
  
  return (
    <aside className="flex flex-col h-full bg-white border-r border-slate-200 w-[240px]">
      {/* Logo */}
      <div className="px-5 py-5 border-b border-slate-100">
        <Link to="/" className="font-syne font-extrabold text-xl text-slate-900 tracking-tight">
          Stag<span className="text-[#2E7DF7]">.</span>io
        </Link>
        <div className="mt-0.5 text-xs text-slate-400 font-medium">Student Portal</div>
      </div>

      {/* Nav */}
      <nav className="flex-1 p-3 space-y-1 overflow-y-auto">
        <div className="text-xs font-semibold text-slate-400 uppercase tracking-widest px-2 py-2">Menu</div>
        {NAV_ITEMS.map(item => (
          <NavLink
            key={item.id}
            to={item.href}
            onClick={closeMobile} // يغلق القائمة في الموبايل عند الضغط
            className={({ isActive }) => 
              `flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                isActive 
                ? "bg-blue-50 text-[#2E7DF7] shadow-sm" 
                : "text-slate-500 hover:bg-slate-50"
              }
            `}
          >
            <span className="text-lg">{item.icon}</span>
            <span>{item.label}</span>
            {item.id === "applications" && (
              <span className="ml-auto bg-blue-100 text-[#2E7DF7] text-[10px] px-2 py-0.5 rounded-full">3</span>
            )}
          </NavLink>
        ))}
      </nav>

      {/* User card */}
      <div className="p-3 border-t border-slate-100">
        <div className="flex items-center gap-3 p-3 rounded-xl hover:bg-slate-50 cursor-pointer transition-colors">
          <div className="w-9 h-9 rounded-full bg-gradient-to-br from-[#5aaee8] to-[#2E7DF7] flex items-center justify-center text-sm font-bold text-white shrink-0">
            AB
          </div>
          <div className="flex-1 min-w-0">
            <div className="text-sm font-semibold text-slate-800 truncate">Amira Benali</div>
            <div className="text-xs text-slate-400 truncate">L3 Informatique · IFA</div>
          </div>
        </div>
        <button className="w-full mt-1 text-xs text-slate-400 hover:text-red-500 py-2 transition-colors text-left px-3 font-bold">
          Sign out →
        </button>
      </div>
    </aside>
  );
}

export default function StudentLayout() {
  const [mobileOpen, setMobileOpen] = useState(false);

  return (
    <div className="flex h-screen overflow-hidden bg-slate-50/50">
      
      {/* Desktop sidebar */}
      <div className="hidden md:flex shrink-0 h-full">
        <Sidebar />
      </div>

      {/* Mobile sidebar overlay & drawer */}
      {mobileOpen && (
        <div className="fixed inset-0 z-50 md:hidden">
          {/* Overlay */}
          <div className="absolute inset-0 bg-slate-900/20 backdrop-blur-sm" onClick={() => setMobileOpen(false)} />
          {/* Drawer */}
          <div className="absolute inset-y-0 left-0 w-[240px] bg-white shadow-2xl animate-in slide-in-from-left duration-300">
            <Sidebar closeMobile={() => setMobileOpen(false)} />
          </div>
        </div>
      )}

      {/* Main content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Mobile topbar */}
        <div className="md:hidden flex items-center justify-between px-4 py-3 bg-white border-b border-slate-200 shadow-sm"></div>
        <button onClick={() => setMobileOpen(true)} className="p-1">
            <span className="text-2xl">☰</span>
          </button>
          <span className="font-syne font-extrabold text-slate-900">Stag<span className="text-[#2E7DF7]">.</span>io</span>
          <div className="w-8 h-8 rounded-full bg-blue-600 flex items-center justify-center text-xs font-bold text-white">AB</div>
        </div>

        <main className="flex-1 overflow-y-auto">
          {/* 👈 التغيير الأهم هنا: Outlet هي التي تعرض الصفحات (Dashboard, Search, etc) */}
          <Outlet /> 
        </main>
      </div>
    
  );
}
